macro_rules! deps {
    () => {
        FuturesUnordered!();
    };
}

macro_rules! FuturesOrdered {
    () => {
        deps!();
        # [doc = " An unbounded queue of futures."] # [doc = ""] # [doc = " This \"combinator\" is similar to [`FuturesUnordered`], but it imposes a FIFO"] # [doc = " order on top of the set of futures. While futures in the set will race to"] # [doc = " completion in parallel, results will only be returned in the order their"] # [doc = " originating futures were added to the queue."] # [doc = ""] # [doc = " Futures are pushed into this queue and their realized values are yielded in"] # [doc = " order. This structure is optimized to manage a large number of futures."] # [doc = " Futures managed by [`FuturesOrdered`] will only be polled when they generate"] # [doc = " notifications. This reduces the required amount of work needed to coordinate"] # [doc = " large numbers of futures."] # [doc = ""] # [doc = " When a [`FuturesOrdered`] is first created, it does not contain any futures."] # [doc = " Calling [`poll_next`](FuturesOrdered::poll_next) in this state will result"] # [doc = " in [`Poll::Ready(None)`](Poll::Ready) to be returned. Futures are submitted"] # [doc = " to the queue using [`push_back`](FuturesOrdered::push_back) (or"] # [doc = " [`push_front`](FuturesOrdered::push_front)); however, the future will"] # [doc = " **not** be polled at this point. [`FuturesOrdered`] will only poll managed"] # [doc = " futures when [`FuturesOrdered::poll_next`] is called. As such, it"] # [doc = " is important to call [`poll_next`](FuturesOrdered::poll_next) after pushing"] # [doc = " new futures."] # [doc = ""] # [doc = " If [`FuturesOrdered::poll_next`] returns [`Poll::Ready(None)`](Poll::Ready)"] # [doc = " this means that the queue is currently not managing any futures. A future"] # [doc = " may be submitted to the queue at a later time. At that point, a call to"] # [doc = " [`FuturesOrdered::poll_next`] will either return the future's resolved value"] # [doc = " **or** [`Poll::Pending`] if the future has not yet completed. When"] # [doc = " multiple futures are submitted to the queue, [`FuturesOrdered::poll_next`]"] # [doc = " will return [`Poll::Pending`] until the first future completes, even if"] # [doc = " some of the later futures have already completed."] # [doc = ""] # [doc = " Note that you can create a ready-made [`FuturesOrdered`] via the"] # [doc = " [`collect`](Iterator::collect) method, or you can start with an empty queue"] # [doc = " with the [`FuturesOrdered::new`] constructor."] # [doc = ""] # [doc = " This type is only available when the `std` or `alloc` feature of this"] # [doc = " library is activated, and it is activated by default."] # [must_use = "streams do nothing unless polled"] pub struct FuturesOrdered < T : Future > { in_progress_queue : FuturesUnordered < OrderWrapper < T > > , queued_outputs : BinaryHeap < OrderWrapper < T :: Output > > , next_incoming_index : i64 , next_outgoing_index : i64 , }
    };
}

FuturesOrdered!();